import React from 'react';import{createRoot}from'react-dom/client';
import SatisfactionDashboard from '../../src/components/satisfaction/SatisfactionDashboard';
import SurveyPage from '../../src/components/satisfaction/SurveyPage';
import type {Survey} from '../../src/components/satisfaction/model';
const original=window.fetch.bind(window);let submitted=false;
window.fetch=async(input,init)=>{const url=String(input);if(url.includes('/rpc/get_ticket_satisfaction'))return new Response(JSON.stringify({case_number:'DEMO-001',specialist_name:'Especialista de demostración',answered:submitted}),{headers:{'Content-Type':'application/json'}});if(url.includes('/rpc/submit_ticket_satisfaction')){submitted=true;return new Response('null',{headers:{'Content-Type':'application/json'}});}return original(input,init);};
const rows:Survey[]=Array.from({length:21},(_,i)=>({id:String(i),ticket_id:String(i),token:'a'.repeat(64),specialist_id:String(Math.floor(i/7)),specialist_name:['Especialista Alfa','Especialista Beta','Especialista Gamma'][Math.floor(i/7)],area:i>13?'quimica':'ingenieria',case_number:`DEMO-${i}`,recipient:null,created_at:new Date().toISOString(),expires_at:new Date(Date.now()+86400000).toISOString(),answered_at:i%7===6?null:new Date().toISOString(),sent_at:null,send_status:'ready',send_error:null,satisfaction:i<7?5:i%2?4:3,speed:i%3+3,resolution:i%4===0?'partial':'total',clarity:i%5===0?null:4,improvement:i%4===0?'followup':'none',comment:null}));
function App(){const[view,setView]=React.useState('dashboard');return <><div style={{padding:16,color:'#454c55',background:'#e0e4e9'}}>DEMOSTRACIÓN · datos ficticios, sin envíos reales <button onClick={()=>setView(view==='dashboard'?'survey':'dashboard')}>{view==='dashboard'?'Probar encuesta':'Ver panel'}</button></div>{view==='dashboard'?<div style={{maxWidth:1200,margin:'auto',padding:16}}><SatisfactionDashboard fixture={rows}/></div>:<SurveyPage/>}</>;}createRoot(document.getElementById('root')!).render(<App/>);
